/**
 * Data access for the MySQL Complete Masterclass. Loader only — the artifact is generated by
 * `scripts/mysql-masterclass.cjs` from `content/mysql-mastery/`.
 */
import { useEffect, useState } from 'react';

export interface SqlTopic {
  id: string;
  title: string;
  simple: string;
  pro: string;
  points: string[];
  example: { sql: string; output: string };
}
export interface SqlQuiz { q: string; options: string[]; answer: string; why: string }
export interface SqlQA { q: string; answer: string }
export interface SqlLab { title: string; task: string; solution: string; expected: string }
export interface SqlDebug { title: string; broken: string; fix: string; error: string; expected: string }
export interface SqlModule {
  id: string; no: number; title: string; goal: string; level: string; hours: number;
  topics: SqlTopic[];
  banks: {
    learn: SqlQuiz[]; interview: SqlQA[]; labs: SqlLab[];
    logic: SqlQA[]; debug: SqlDebug[]; revision: SqlQA[];
  };
}
export interface MysqlMasterclassFile {
  course: {
    id: string; title: string; tagline: string; level: string; hours: number;
    standard: string; prerequisites: string[]; description: string; outcomes: string[];
  };
  stats: {
    modules: number; topics: number; learn: number; interview: number;
    labs: number; logic: number; debug: number; revision: number;
  };
  modules: SqlModule[];
}

let cached: Promise<MysqlMasterclassFile> | null = null;

function load(): Promise<MysqlMasterclassFile> {
  if (!cached) {
    cached = fetch('generated/mysql-masterclass/index.json')
      .then((r) => {
        if (!r.ok) throw new Error(`mysql-masterclass/index.json: ${r.status}`);
        return r.json() as Promise<MysqlMasterclassFile>;
      })
      .catch((error) => { cached = null; throw error; });
  }
  return cached;
}

export function useMysqlMasterclass(): MysqlMasterclassFile | null {
  const [data, setData] = useState<MysqlMasterclassFile | null>(null);
  useEffect(() => {
    let live = true;
    load().then((d) => { if (live) setData(d); }).catch(() => { /* the page shows its loading state */ });
    return () => { live = false; };
  }, []);
  return data;
}
